void record_rev_key_event(uint32_t key,lv_obj_t * ui_Screen)
{
    ui_screen_record_list_obj_t * p_screen_param;
    lv_obj_t *      list = get_record_rev_select_list_obj(ui_Screen);

    ;
    uint32_t        child_cnt = lv_obj_get_child_cnt(list);
    uint32_t        child_id = get_list_child_focused_id(list,child_cnt);
    lv_obj_t *      get_focus_obj = NULL;
    lv_obj_t *      pre_focus_obj = NULL;
    lv_obj_t *      label;

    p_screen_param      = (ui_screen_record_list_obj_t *) lv_obj_get_user_data(ui_Screen);

    //__inf("sms_menu_key_event key:%d,child_id:%d,child_cnt:%d\r\n",key,child_id,child_cnt);
    switch (key)
    {
        case LV_KEY_UP:
            {
                if (child_cnt <= 1)
                    return;

                if (child_id != 0) {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);


                    get_focus_obj       = lv_obj_get_child(list,child_id - 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    if ((child_id - 1) == 0) {
                        lv_obj_scroll_to_y(list,0,LV_ANIM_OFF);
                        }
                    else {
                        lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                        }
                    }
                else {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,child_cnt - 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                    }

                label               = lv_obj_get_child(pre_focus_obj,0);
                lv_label_set_long_mode(label,LV_LABEL_LONG_CLIP);

                label               = lv_obj_get_child(get_focus_obj,0);
                lv_label_set_long_mode(label,LV_LABEL_LONG_SCROLL);
                }
            break;

        case LV_KEY_DOWN:
            {
                if (child_cnt <= 1)
                    return;

                if (child_id != child_cnt - 1) {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,child_id + 1);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_view(get_focus_obj,LV_ANIM_OFF);
                    }
                else {
                    pre_focus_obj       = lv_obj_get_child(list,child_id);
                    lv_obj_clear_state(pre_focus_obj,LV_STATE_FOCUSED);

                    get_focus_obj       = lv_obj_get_child(list,0);
                    lv_obj_add_state(get_focus_obj,LV_STATE_FOCUSED);

                    lv_obj_scroll_to_y(list,0,LV_ANIM_OFF);
                    }

                label               = lv_obj_get_child(pre_focus_obj,0);
                lv_label_set_long_mode(label,LV_LABEL_LONG_CLIP);

                label               = lv_obj_get_child(get_focus_obj,0);
                lv_label_set_long_mode(label,LV_LABEL_LONG_SCROLL);
                }
            break;

        case LV_KEY_ENTER:
            {
                screen_record_play_enter_param_t enter_param;

                get_focus_obj       = lv_obj_get_child(p_screen_param->obj_list,child_id);
                enter_param.d_off   = (uint32_t) lv_obj_get_user_data(get_focus_obj);
                alv_am_win_enter(NULL,"record_play",&enter_param);
                }
            break;

        case APP_KEY_VALUE_TOP_LEFT:
            {
                ui_ScreenRecordList_del_remind(ui_Screen);
                }
            break;

        case APP_KEY_VALUE_TOP_RIGHT:
            {
                alv_am_win_exit_current(NULL);
                }
            break;

        case LV_KEY_END:
            alv_am_app_exit_action_all();
            break;
        }
}


