static void remind_timer_callback_record_list_rev(screen_remind_param_t * p_screen_remind_param)
{
    lv_obj_t *      ui_screen;
    list_rev_win_param_t * p_param;

    p_param             = p_screen_remind_param->user_data;

    ui_screen           = ui_ScreenRecordList_screen_init(NULL,p_param);
    p_param->ui_main    = ui_screen;

    if (p_param->focus_status == 0)
        return;

    lv_disp_load_scr(ui_screen);
}




lv_obj_t * ui_ScreenRecordList_screen_active(lv_obj_t * win,void * param)
{
    screen_remind_param_t screen_remind_param;
    lv_obj_t *      ui_screen;
    list_rev_win_param_t * p_param;

    p_param             = lv_mem_alloc(sizeof(list_rev_win_param_t));
    p_param->ui_remind  = NULL;
    p_param->ui_main    = NULL;
    p_param->focus_status = 0;

    ui_screen_remind_param_init(&screen_remind_param);
    screen_remind_param.str = "正打开";
    screen_remind_param.tiemr_delay = 700;
    screen_remind_param.fun = (remind_timer_callback_fun_t) remind_timer_callback_record_list_rev;
    screen_remind_param.user_data = p_param;
    screen_remind_param.self_destory_flag = 0;
    screen_remind_param.key_exit_enable = 0;

    ui_screen           = ui_screen_remind_init(&screen_remind_param);

    p_param->ui_remind  = ui_screen;

    lv_obj_set_user_data(win,p_param);

    return ui_screen;
}


void ui_ScreenRecordList_screen_deactive(lv_obj_t * win,void * param)
{

    list_rev_win_param_t * p_param;

    p_param             = (list_rev_win_param_t *) lv_obj_get_user_data(win);
    ui_screen_remind_uninit(p_param->ui_remind);
    ui_ScreenRecordList_screen_uninit(p_param->ui_main,param);

    lv_mem_free(p_param);
    lv_obj_set_user_data(win,NULL);
}


void ui_ScreenRecordList_win_focus(lv_obj_t * win,void * param)
{
    list_rev_win_param_t * p_param;

    p_param             = (list_rev_win_param_t *) lv_obj_get_user_data(win);
    lv_obj_t *      ui_screen = NULL;

    if (p_param->ui_main)
        ui_screen = p_param->ui_main;
    else if (p_param->ui_remind)
        ui_screen = p_param->ui_remind;

    if (ui_screen)
        lv_disp_load_scr(ui_screen);

    p_param->focus_status = 1;
}

void ui_ScreenRecordList_win_defocus(lv_obj_t * win,void * param)
{
    list_rev_win_param_t * p_param;

    p_param             = lv_obj_get_user_data(win);

    p_param->focus_status = 0;
}

static void remind_timer_callback_record_list_del(screen_remind_param_t * p_screen_remind_param)
{
    list_rev_win_param_t * p_param;
    ui_screen_record_list_obj_t * p_screen_param;
    lv_obj_t *      ui_screen,*ui_screen1;
    uint32_t        file_d_off;
    uint32_t        child_cnt;
    uint32_t        child_id;
    lv_obj_t *      get_focus_obj = NULL;

    ui_screen           = p_screen_remind_param->user_data;
    p_screen_param      = (ui_screen_record_list_obj_t *) lv_obj_get_user_data(ui_screen);

    child_cnt           = lv_obj_get_child_cnt(p_screen_param->obj_list);
    child_id            = get_list_child_focused_id(p_screen_param->obj_list,child_cnt);
    get_focus_obj       = lv_obj_get_child(p_screen_param->obj_list,child_id);
    file_d_off          = (uint32_t) lv_obj_get_user_data(get_focus_obj);
    fp_del_file_by_folder_off(APP_RECORDER_FILE_DIR,file_d_off);

    if (is_recorder_folder_empty()) {
        alv_am_win_exit_current(NULL);
        return;
        }

    p_param             = p_screen_param->param;
    ui_screen1          = ui_ScreenRecordList_screen_init(NULL,p_param);
    p_param->ui_main    = ui_screen1;

    ui_ScreenRecordList_screen_uninit(ui_screen,NULL);

    lv_disp_load_scr(ui_screen1);

}




